let products=[...fallbackProducts];
const rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value);
const escapeAttr=value=>String(value||'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const state={query:'',category:'Semua',material:'all',stock:'all',sort:'featured'};
let cart=JSON.parse(localStorage.getItem('ruangrupa-cart')||'[]'),activeProduct=null,appliedVoucher=null,shippingQuoteReady=false,shippingRequest=0;
const grid=document.querySelector('#productGrid'),count=document.querySelector('#catalogCount'),filters=document.querySelector('#categoryFilters');
const productDialog=document.querySelector('#productDialog'),cartDialog=document.querySelector('#cartDialog'),checkoutDialog=document.querySelector('#checkoutDialog');
const checkoutError=document.createElement('div');checkoutError.id='checkoutError';checkoutError.setAttribute('role','alert');checkoutError.hidden=true;checkoutError.style.cssText='margin-top:18px;padding:14px 16px;border:1px solid #dba38b;border-radius:12px;background:#fff0e8;color:#8b3820;line-height:1.5';document.querySelector('#checkoutForm .submit-order[type="submit"]').before(checkoutError);
function showCheckoutError(message){checkoutError.textContent=message?`Pesanan belum berhasil dibuat. ${message}`:'';checkoutError.hidden=!message;if(message)checkoutError.scrollIntoView({behavior:'smooth',block:'center'})}
function chooseCategory(category,scroll=false){state.category=category;document.querySelectorAll('.filter-chip').forEach(item=>item.classList.toggle('active',item.dataset.category===category));document.querySelectorAll('.category').forEach(item=>item.classList.toggle('active',item.dataset.category===category));renderProducts();if(scroll)document.querySelector('#ruangan').scrollIntoView({behavior:'smooth'})}
function renderFilters(){filters.innerHTML='';['Semua',...new Set(products.map(product=>product.category))].forEach(category=>{const button=document.createElement('button');button.className='filter-chip'+(category===state.category?' active':'');button.dataset.category=category;button.textContent=category;button.addEventListener('click',()=>chooseCategory(category));filters.append(button)});document.querySelectorAll('[data-category-count]').forEach(item=>{const total=products.filter(product=>product.category===item.dataset.categoryCount).length;item.textContent=`${total} produk`})}
async function loadCatalog(){try{const response=await fetch('/api/products'),data=await response.json();if(!response.ok)throw new Error();products=data.products.map(item=>{const visual=fallbackProducts.find(product=>product.id===item.id)||{},art=visual.art||({Sofa:'sofa',Kursi:'chair',Meja:'table',Lemari:'cabinet','Tempat tidur':'bed'}[item.category]||'table');return{...visual,...item,art,imageUrl:item.imageUrl||visual.imageUrl||'',meta:`${item.material} · ${item.dimensions}`,size:item.dimensions,colors:visual.colors||['#d9c9b5','#6f7d72'],tag:item.stock<=2?'Stok terbatas':visual.tag||''}});cart=cart.filter(item=>products.some(product=>product.id===item.id));saveCart();renderFilters();renderProducts()}catch{products=[...fallbackProducts];renderFilters();renderProducts();renderCart()}}
function stockInfo(product){if(product.stock<1)return{label:'Stok habis',className:'out'};if(product.stock<=2)return{label:`Tersisa ${product.stock} unit`,className:'low'};return{label:'Tersedia',className:''}}
function renderProducts(){let list=products.filter(product=>(state.category==='Semua'||product.category===state.category)&&(state.material==='all'||product.material===state.material)&&(state.stock==='all'||state.stock==='available'&&product.stock>0||state.stock==='low'&&product.stock>0&&product.stock<=2||state.stock==='out'&&product.stock<1)&&(product.name+' '+product.meta+' '+product.description).toLowerCase().includes(state.query));if(state.sort==='low')list.sort((a,b)=>a.price-b.price);if(state.sort==='high')list.sort((a,b)=>b.price-a.price);if(state.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'id'));const active=state.query||state.category!=='Semua'||state.material!=='all'||state.stock!=='all'||state.sort!=='featured';document.querySelector('#resetFilters').hidden=!active;count.textContent=`Menampilkan ${list.length} dari ${products.length} produk`;grid.innerHTML=list.length?list.map(product=>{const stock=stockInfo(product);return `<article class="product"><div class="product-art ${product.art}">${product.imageUrl?`<img class="product-photo" src="${escapeAttr(product.imageUrl)}" alt="${escapeAttr(product.name)}" loading="lazy">`:''}${product.tag?`<span class="tag">${escapeAttr(product.tag)}</span>`:''}</div><div class="product-body"><h3>${escapeAttr(product.name)}</h3><div class="meta">${escapeAttr(product.meta)}</div><div class="availability ${stock.className}">${stock.label}</div><div class="price">${rupiah(product.price)}</div><button class="btn" data-detail="${product.id}">Lihat detail</button></div></article>`}).join(''):'<div class="empty"><strong>Produk tidak ditemukan.</strong><br>Coba kata kunci atau hapus filter yang aktif.</div>';grid.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>openDetail(Number(button.dataset.detail))))}
function openDetail(id){activeProduct=products.find(item=>item.id===id);const art=document.querySelector('#detailArt');art.className=`product-art detail-art ${activeProduct.art}`;art.innerHTML=activeProduct.imageUrl?`<img class="product-photo" src="${escapeAttr(activeProduct.imageUrl)}" alt="${escapeAttr(activeProduct.name)}">`:'';document.querySelector('#detailCategory').textContent=activeProduct.category;document.querySelector('#detailTitle').textContent=activeProduct.name;document.querySelector('#detailMeta').textContent=activeProduct.meta;document.querySelector('#detailPrice').textContent=rupiah(activeProduct.price);document.querySelector('#detailDescription').textContent=activeProduct.description;document.querySelector('#detailSize').textContent=activeProduct.size;document.querySelector('#detailStock').textContent=`${activeProduct.stock} unit`;document.querySelector('#detailColors').innerHTML=activeProduct.colors.map(color=>`<span class="swatch" style="background:${color}"></span>`).join('');document.querySelector('#detailAdd').disabled=activeProduct.stock<1;document.querySelector('#detailAdd').textContent=activeProduct.stock<1?'Stok habis':'Tambah ke keranjang';productDialog.showModal()}
function saveCart(){localStorage.setItem('ruangrupa-cart',JSON.stringify(cart));renderCart()}
function addToCart(id){const product=products.find(item=>item.id===id),item=cart.find(entry=>entry.id===id);if(item)item.qty=Math.min(item.qty+1,product.stock);else cart.push({id,qty:1});saveCart();productDialog.close();cartDialog.showModal()}
function cartTotals(){const subtotal=cart.reduce((sum,item)=>sum+products.find(product=>product.id===item.id).price*item.qty,0);return{subtotal,totalQty:cart.reduce((sum,item)=>sum+item.qty,0)}}
function renderCart(){const list=document.querySelector('#cartList'),foot=document.querySelector('#cartFoot'),{subtotal,totalQty}=cartTotals(),badge=document.querySelector('#cartBadge');badge.textContent=totalQty;badge.style.display=totalQty?'grid':'none';foot.hidden=!cart.length;if(!cart.length){list.innerHTML='<div class="cart-empty"><strong>Keranjang masih kosong.</strong><br>Tambahkan produk dari katalog.</div>';return}list.innerHTML=cart.map(item=>{const product=products.find(entry=>entry.id===item.id);return `<article class="cart-item"><div class="product-art cart-thumb ${product.art}"></div><div><h3>${product.name}</h3><small>${rupiah(product.price)}</small><div class="qty"><button data-qty="${product.id}" data-delta="-1" aria-label="Kurangi">−</button><strong>${item.qty}</strong><button data-qty="${product.id}" data-delta="1" aria-label="Tambah">+</button></div></div><button class="remove" data-remove="${product.id}" aria-label="Hapus">×</button></article>`}).join('');document.querySelector('#cartSubtotal').textContent=rupiah(subtotal);list.querySelectorAll('[data-qty]').forEach(button=>button.addEventListener('click',()=>changeQty(Number(button.dataset.qty),Number(button.dataset.delta))));list.querySelectorAll('[data-remove]').forEach(button=>button.addEventListener('click',()=>{cart=cart.filter(item=>item.id!==Number(button.dataset.remove));saveCart()}))}
function changeQty(id,delta){const item=cart.find(entry=>entry.id===id),product=products.find(entry=>entry.id===id);item.qty=Math.max(0,Math.min(product.stock,item.qty+delta));if(!item.qty)cart=cart.filter(entry=>entry.id!==id);saveCart()}
function updateCheckout(){const subtotal=cartTotals().subtotal,shipping=shippingQuoteReady?Number(document.querySelector('#shipping').value):0,discountValue=Number(appliedVoucher?.discount||0),total=subtotal+shipping-discountValue,items=document.querySelector('#checkoutItems');items.innerHTML=cart.map(item=>{const product=products.find(entry=>entry.id===item.id);return `<div class="checkout-item"><span>${escapeAttr(product.name)}<small>${item.qty} × ${rupiah(product.price)}</small></span><strong>${rupiah(product.price*item.qty)}</strong></div>`}).join('');document.querySelector('#checkoutSubtotal').textContent=rupiah(subtotal);document.querySelector('#checkoutShipping').textContent=shippingQuoteReady?rupiah(shipping):'Belum dihitung';document.querySelector('#checkoutDiscount').textContent='− '+rupiah(discountValue);document.querySelector('#checkoutTotal').textContent=rupiah(total)}
async function requestShippingQuote(){const city=document.querySelector('#city').value.trim(),postalCode=document.querySelector('#postal').value.trim(),label=document.querySelector('#shippingLabel'),zone=document.querySelector('#shippingZone'),requestId=++shippingRequest;shippingQuoteReady=false;document.querySelector('#shipping').value='0';label.classList.remove('ready');if(city.length<2||!/^[0-9]{5}$/.test(postalCode)){label.textContent='Lengkapi kota dan kode pos';zone.textContent='Ongkir dihitung otomatis berdasarkan tujuan.';updateCheckout();return false}label.textContent='Menghitung ongkir…';updateCheckout();try{const response=await fetch(`/api/shipping/quote?city=${encodeURIComponent(city)}&postalCode=${encodeURIComponent(postalCode)}`),data=await response.json();if(requestId!==shippingRequest)return false;if(!response.ok)throw new Error(data.error||'Ongkir belum tersedia');document.querySelector('#shipping').value=String(data.cost);shippingQuoteReady=true;label.textContent=`${data.zone} · ${rupiah(data.cost)}`;label.classList.add('ready');zone.textContent=`Estimasi pengiriman ${data.estimate}.`;updateCheckout();return true}catch(error){if(requestId!==shippingRequest)return false;label.textContent='Ongkir belum dapat dihitung';zone.textContent=error.message;updateCheckout();return false}}
document.querySelector('#searchInput').addEventListener('input',event=>{state.query=event.target.value.trim().toLowerCase();renderProducts()});
document.querySelector('#materialFilter').addEventListener('change',event=>{state.material=event.target.value;renderProducts()});
document.querySelector('#stockFilter').addEventListener('change',event=>{state.stock=event.target.value;renderProducts()});
document.querySelector('#sortSelect').addEventListener('change',event=>{state.sort=event.target.value;renderProducts()});
document.querySelector('#resetFilters').addEventListener('click',()=>{state.query='';state.category='Semua';state.material='all';state.stock='all';state.sort='featured';document.querySelector('#searchInput').value='';document.querySelector('#materialFilter').value='all';document.querySelector('#stockFilter').value='all';document.querySelector('#sortSelect').value='featured';chooseCategory('Semua')});
document.querySelectorAll('.category').forEach(button=>button.addEventListener('click',()=>chooseCategory(button.dataset.category,true)));
document.querySelector('#detailClose').addEventListener('click',()=>productDialog.close());
productDialog.addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close()});
document.querySelector('#detailAdd').addEventListener('click',()=>addToCart(activeProduct.id));
document.querySelector('#cartOpen').addEventListener('click',()=>cartDialog.showModal());document.querySelector('#cartClose').addEventListener('click',()=>cartDialog.close());
document.querySelector('#checkoutOpen').addEventListener('click',()=>{cartDialog.close();showCheckoutError('');appliedVoucher=null;shippingQuoteReady=false;document.querySelector('#shipping').value='0';document.querySelector('#voucher').value='';document.querySelector('#voucherMessage').textContent='';document.querySelector('#checkoutContent').hidden=false;document.querySelector('#checkoutSuccess').hidden=true;const profile=JSON.parse(localStorage.getItem('ruangrupa-profile')||'null'),addresses=JSON.parse(localStorage.getItem('ruangrupa-addresses')||'[]');if(profile){document.querySelector('#customerName').value=profile.name;document.querySelector('#phone').value=profile.phone;document.querySelector('#customerEmail').value=profile.email||''}if(addresses.length){const address=addresses[0];document.querySelector('#address').value=address.text;document.querySelector('#city').value=address.city;document.querySelector('#postal').value=address.postalCode||''}updateCheckout();checkoutDialog.showModal();requestShippingQuote()});
document.querySelector('#checkoutClose').addEventListener('click',()=>checkoutDialog.close());
document.querySelector('#voucherApply').addEventListener('click',async()=>{const button=document.querySelector('#voucherApply'),message=document.querySelector('#voucherMessage'),code=document.querySelector('#voucher').value.trim().toUpperCase(),subtotal=cartTotals().subtotal;appliedVoucher=null;if(!code){message.textContent='Masukkan kode voucher';message.style.color='#a8552f';updateCheckout();return}button.disabled=true;button.textContent='Memeriksa…';try{const response=await fetch('/api/promotions/validate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code,subtotal})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Voucher belum dapat digunakan');appliedVoucher=data;document.querySelector('#voucher').value=data.code;message.textContent=`${data.name} aktif: hemat ${rupiah(data.discount)}`;message.style.color='#376446'}catch(error){message.textContent=error.message;message.style.color='#a8552f'}finally{button.disabled=false;button.textContent='Pakai';updateCheckout()}});
document.querySelector('#checkoutForm').addEventListener('submit',async event=>{event.preventDefault();showCheckoutError('');const form=event.currentTarget;if(!form.reportValidity())return;const button=event.submitter;button.disabled=true;button.textContent='Menghitung ongkir…';if(!await requestShippingQuote()){showCheckoutError('Ongkir belum dapat dihitung. Periksa kota dan kode pos.');button.disabled=false;button.textContent='Buat pesanan simulasi';return}button.textContent='Membuat pesanan…';const shipping=Number(document.querySelector('#shipping').value),payload={customerName:document.querySelector('#customerName').value.trim(),customerPhone:document.querySelector('#phone').value.trim(),customerEmail:document.querySelector('#customerEmail').value.trim(),address:document.querySelector('#address').value.trim(),city:document.querySelector('#city').value.trim(),postalCode:document.querySelector('#postal').value.trim(),shipping,voucher:appliedVoucher?.code||'',items:cart.map(item=>({id:item.id,qty:item.qty}))};try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error||'Pesanan belum dapat dibuat');const order={...data.order,createdAt:new Date().toISOString(),expiresAt:data.order.expiresAt||new Date(Date.now()+86400000).toISOString(),method:'Virtual Account',customer:{name:payload.customerName,phone:payload.customerPhone,email:payload.customerEmail,address:payload.address,city:payload.city,postal:payload.postalCode},items:cart.map(item=>({...item,name:products.find(product=>product.id===item.id).name,price:products.find(product=>product.id===item.id).price}))};const orders=JSON.parse(localStorage.getItem('ruangrupa-orders')||'[]');orders.unshift(order);localStorage.setItem('ruangrupa-orders',JSON.stringify(orders));localStorage.setItem('ruangrupa-current-order',order.id);cart=[];saveCart();location.href='payment.html?order='+encodeURIComponent(order.id)}catch(error){showCheckoutError(error.message);button.disabled=false;button.textContent='Buat pesanan simulasi'}});
document.querySelector('#successClose').addEventListener('click',()=>checkoutDialog.close());
const checkoutSummary=document.querySelector('.checkout-summary'),checkoutItems=document.createElement('div');checkoutItems.id='checkoutItems';checkoutItems.className='checkout-items';checkoutSummary.prepend(checkoutItems);const emailField=document.createElement('div');emailField.className='field full';emailField.innerHTML='<label for="customerEmail">Email untuk notifikasi pesanan</label><input id="customerEmail" type="email" required autocomplete="email" placeholder="nama@email.com">';document.querySelector('#address').closest('.field').before(emailField);const phoneInput=document.querySelector('#phone'),postalInput=document.querySelector('#postal'),nameInput=document.querySelector('#customerName'),addressInput=document.querySelector('#address'),cityInput=document.querySelector('#city');phoneInput.pattern='(?:\\+62|62|0)[0-9]{8,13}';phoneInput.title='Gunakan nomor Indonesia, misalnya 081234567890';phoneInput.autocomplete='tel';postalInput.pattern='[0-9]{5}';postalInput.maxLength=5;postalInput.title='Kode pos harus terdiri dari 5 angka';postalInput.autocomplete='postal-code';nameInput.minLength=3;addressInput.minLength=10;addressInput.autocomplete='street-address';cityInput.minLength=2;cityInput.autocomplete='address-level2';cityInput.addEventListener('change',requestShippingQuote);postalInput.addEventListener('input',()=>{if(postalInput.value.length===5)requestShippingQuote()});
renderFilters();renderProducts();renderCart();loadCatalog();(async()=>{try{const sessionResponse=await fetch('/api/customer/session'),session=await sessionResponse.json();if(!session.authenticated)return;localStorage.setItem('ruangrupa-profile',JSON.stringify(session.customer));const addressResponse=await fetch('/api/customer/addresses'),addressData=await addressResponse.json();if(addressResponse.ok)localStorage.setItem('ruangrupa-addresses',JSON.stringify(addressData.addresses))}catch{}})();
